using System.Collections.Generic;
using System.Text;
using MasterDataTool.Runtime;

namespace MasterDataTool.EditorTools.Generation
{
    /// <summary>
    /// 生成 C# ソースのテンプレートです。
    /// </summary>
    public static class CodeTemplates
    {
        const string AutoGeneratedHeader =
            "// <auto-generated>\n" +
            "// このファイルは Master Data Tool によって生成されました。\n" +
            "// 再生成すると上書きされるため、直接編集しないでください。\n" +
            "// </auto-generated>\n";

        const string RecordUsings =
            "using System;\n" +
            "using System.Collections.Generic;\n" +
            "using MasterDataTool.Runtime;\n" +
            "using UnityEngine;\n";

        const string MasterUsings =
            "using MasterDataTool.Runtime;\n" +
            "using UnityEngine;\n";

        /// <summary>
        /// レコード型のソースを組み立てます。
        /// </summary>
        /// <param name="options">生成オプションです。</param>
        /// <param name="schema">スキーマです。</param>
        /// <returns>レコード型のソース文字列です。</returns>
        internal static string BuildRecordSource(MasterCodeOptions options, MasterSchema schema)
        {
            var idBase = schema.IdKind == MasterIdKind.Int ? "IntIdMasterRecord" : "StringIdMasterRecord";
            var fieldsBuilder = new StringBuilder();
            var propertiesBuilder = new StringBuilder();

            for (var i = 0; i < schema.Fields.Count; i++)
            {
                var field = schema.Fields[i];
                if (fieldsBuilder.Length > 0)
                {
                    fieldsBuilder.Append('\n');
                }

                if (propertiesBuilder.Length > 0)
                {
                    propertiesBuilder.Append('\n');
                }

                if (field.IsList)
                {
                    fieldsBuilder.Append("        [SerializeField] private List<");
                    fieldsBuilder.Append(GetListElementTypeName(field.Type));
                    fieldsBuilder.Append("> ");
                    fieldsBuilder.Append(field.JsonName);
                    fieldsBuilder.Append(" = new List<");
                    fieldsBuilder.Append(GetListElementTypeName(field.Type));
                    fieldsBuilder.Append(">();");

                    propertiesBuilder.Append("        public IReadOnlyList<");
                    propertiesBuilder.Append(GetListElementTypeName(field.Type));
                    propertiesBuilder.Append("> ");
                    propertiesBuilder.Append(field.PropertyName);
                    propertiesBuilder.Append(" => ");
                    propertiesBuilder.Append(field.JsonName);
                    propertiesBuilder.Append(";");
                }
                else
                {
                    fieldsBuilder.Append("        [SerializeField] private ");
                    fieldsBuilder.Append(field.CSharpTypeName);
                    fieldsBuilder.Append(' ');
                    fieldsBuilder.Append(field.JsonName);
                    fieldsBuilder.Append(';');

                    propertiesBuilder.Append("        public ");
                    propertiesBuilder.Append(field.CSharpTypeName);
                    propertiesBuilder.Append(' ');
                    propertiesBuilder.Append(field.PropertyName);
                    propertiesBuilder.Append(" => ");
                    propertiesBuilder.Append(field.JsonName);
                    propertiesBuilder.Append(';');
                }
            }

            var bodyBuilder = new StringBuilder();
            bodyBuilder.Append("    {\n");
            if (fieldsBuilder.Length > 0)
            {
                bodyBuilder.Append(fieldsBuilder);
                bodyBuilder.Append('\n');
                bodyBuilder.Append('\n');
                bodyBuilder.Append(propertiesBuilder);
                bodyBuilder.Append('\n');
            }

            bodyBuilder.Append("    }");

            var builder = new StringBuilder();
            builder.Append(AutoGeneratedHeader);
            builder.Append(RecordUsings);
            builder.Append('\n');
            builder.Append("namespace ");
            builder.Append(options.Namespace);
            builder.Append("\n{\n");
            builder.Append("    [Serializable]\n");
            builder.Append("    public sealed class ");
            builder.Append(options.MasterName);
            builder.Append("Record : ");
            builder.Append(idBase);
            builder.Append("\n");
            builder.Append(bodyBuilder);
            builder.Append("\n}\n");

            return builder.ToString();
        }

        /// <summary>
        /// マスタ型のソースを組み立てます。
        /// </summary>
        /// <param name="options">生成オプションです。</param>
        /// <returns>マスタ型のソース文字列です。</returns>
        internal static string BuildMasterSource(MasterCodeOptions options)
        {
            var builder = new StringBuilder();
            builder.Append(AutoGeneratedHeader);
            builder.Append(MasterUsings);
            builder.Append('\n');
            builder.Append("namespace ");
            builder.Append(options.Namespace);
            builder.Append("\n{\n");
            builder.Append("    [CreateAssetMenu(fileName = \"");
            builder.Append(options.MasterName);
            builder.Append("Master\", menuName = \"Master Data/");
            builder.Append(options.MasterName);
            builder.Append("\")]\n");
            builder.Append("    public sealed class ");
            builder.Append(options.MasterName);
            builder.Append("Master : MasterDataBase<");
            builder.Append(options.MasterName);
            builder.Append("Record>\n");
            builder.Append("    {\n");
            builder.Append("    }\n");
            builder.Append("}\n");

            return builder.ToString();
        }

        static string GetListElementTypeName(SchemaFieldType type)
        {
            switch (type)
            {
                case SchemaFieldType.Int:
                    return "int";
                case SchemaFieldType.Long:
                    return "long";
                case SchemaFieldType.Float:
                    return "float";
                case SchemaFieldType.Bool:
                    return "bool";
                default:
                    return "string";
            }
        }
    }
}
